def bfs(graph, start):
    visited = {start}
    queue = [start]
    order = []
    while queue:
        node = queue.pop(0)
        order.append(node)
        for neighbor in graph.edges.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

def dfs(graph, start):
    visited = set()
    order = []
    dfs_visit(graph, start, visited, order)
    return order


def dfs_visit(graph, node, visited, order):
    if node in visited:
        return
    visited.add(node)
    order.append(node)
    for neighbor in graph.edges.get(node, []):
        dfs_visit(graph, neighbor, visited, order)

class WeightedGraph:
    def __init__(self):
        self.edges = {}

    def add_edge(self, from_node, to_node, weight):
        self.edges.setdefault(from_node, []).append((to_node, weight))
        self.edges.setdefault(to_node, []).append((from_node, weight))


def dijkstra(graph, start, nodes):
    dist = {node: float("inf") for node in nodes}
    visited = set()
    dist[start] = 0

    while len(visited) < len(nodes):
        current = closest_unvisited(dist, visited)
        if current is None:
            break
        visited.add(current)
        for neighbor, weight in graph.edges.get(current, []):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
    return dist


def closest_unvisited(dist, visited):
    best = None
    best_dist = float("inf")
    for node, d in dist.items():
        if node not in visited and d < best_dist:
            best = node
            best_dist = d
    return best
